// Luyện nói theo chủ đề: 32 câu hỏi, mỗi bài nói mẫu gồm 5 phần × 3 câu = 15 câu (câu Trung – nghĩa Việt).
// Có thể thay tên, thời gian, địa điểm, sở thích cho đúng bản thân.
export const SPEAK_INTRO = "26 chủ đề luyện nói HSK 1–2 với 390 câu mẫu. Mỗi bài trình bày thành 3 cột: Tiếng Trung – Tiếng Việt – Pinyin. Bạn có thể thay tên, thời gian, địa điểm và sở thích cho đúng bản thân.";
export const SPEAK_GROUPS = [["A","Bản thân và bạn bè","👤"],["B","Sinh hoạt hằng ngày","⏰"],["C","Sở thích","🎨"],["D","Học tập và công việc","📚"],["E","Nấu ăn và việc nhà","🍳"],["F","Sức khỏe","💪"],["G","Niềm vui và kỷ niệm","🎁"],["H","Nếu… và lựa chọn","💭"]];
export const SPEAK_ITEMS = [{"id":1,"q":"请介绍一下自己？","qvi":"Giới thiệu bản thân","s":[["我叫黎辉遵。","Tôi tên là Lê Huy Tuân.","Wǒ jiào Lí Huī Zūn."],["我今年二十五岁。","Năm nay tôi 25 tuổi.","Wǒ jīn nián èr shí wǔ suì."],["我是越南人。","Tôi là người Việt Nam.","Wǒ shì Yuè nán rén."],["我家在越南义安。","Nhà tôi ở Nghệ An, Việt Nam.","Wǒ jiā zài Yuè nán Yì ān."],["我以前在莫斯科上大学。","Trước đây tôi học đại học ở Moscow.","Wǒ yǐ qián zài Mò sī kē shàng dà xué."],["我的大学在莫斯科。","Trường đại học của tôi nằm ở Moscow.","Wǒ de dà xué zài Mò sī kē."],["我在莫斯科学习了四年。","Tôi đã học ở Moscow bốn năm.","Wǒ zài Mò sī kē xué xí le sì nián."],["我的专业是信息技术。","Chuyên ngành của tôi là công nghệ thông tin.","Wǒ de zhuān yè shì xìn xī jì shù."],["我很喜欢这个专业。","Tôi rất thích chuyên ngành này.","Wǒ hěn xǐ huan zhè ge zhuān yè."],["因为我很喜欢电脑。","Bởi vì tôi rất thích máy tính.","Yīn wèi wǒ hěn xǐ huan diàn nǎo."],["上大学的时候，我每天都去学校。","Khi học đại học, ngày nào tôi cũng đến trường.","Shàng dà xué de shí hou, wǒ měi tiān dōu qù xué xiào."],["下课以后，我经常在家做作业。","Sau khi tan học, tôi thường làm bài tập ở nhà.","Xià kè yǐ hòu, wǒ jīng cháng zài jiā zuò zuò yè."],["现在我已经不上大学了。","Bây giờ tôi không còn học đại học nữa.","Xiàn zài wǒ yǐ jīng bù shàng dà xué le."],["我现在正在学习汉语。","Hiện tại tôi đang học tiếng Trung.","Wǒ xiàn zài zhèng zài xué xí hàn yǔ."],["我想在信息技术公司工作。","Tôi muốn làm việc tại một công ty công nghệ thông tin.","Wǒ xiǎng zài xìn xī jì shù gōng sī gōng zuò."]],"g":"A"},{"id":2,"q":"你家有几口人？请介绍一下你的家人。","qvi":"Giới thiệu gia đình","s":[["我家有五口人。","Gia đình tôi có năm người.","Wǒ jiā yǒu wǔ kǒu rén."],["有爸爸、妈妈、两个哥哥和我。","Gồm bố, mẹ, hai anh trai và tôi.","Yǒu bà ba, mā ma, liǎng ge gē ge hé wǒ."],["我家在越南义安。","Nhà tôi ở Nghệ An, Việt Nam.","Wǒ jiā zài Yuè nán Yì ān."],["我的爸爸每天都工作。","Bố tôi đi làm mỗi ngày.","Wǒ de bà ba měi tiān dōu gōng zuò."],["他早上去上班，晚上回家。","Bố đi làm buổi sáng và về nhà buổi tối.","Tā zǎo shang qù shàng bān, wǎn shang huí jiā."],["我的妈妈每天都很忙。","Mẹ tôi ngày nào cũng rất bận.","Wǒ de mā ma měi tiān dōu hěn máng."],["她经常在家做饭。","Mẹ thường nấu ăn ở nhà.","Tā jīng cháng zài jiā zuò fàn."],["妈妈做的饭非常好吃。","Món ăn mẹ nấu rất ngon.","Mā ma zuò de fàn fēi cháng hǎo chī."],["我有两个哥哥。","Tôi có hai anh trai.","Wǒ yǒu liǎng ge gē ge."],["他们都已经工作了。","Cả hai anh đều đã đi làm.","Tā men dōu yǐ jīng gōng zuò le."],["因为他们工作很忙，所以我们不经常见面。","Vì công việc của các anh rất bận nên chúng tôi không thường gặp nhau.","Yīn wèi tā men gōng zuò hěn máng, suǒ yǐ wǒ men bù jīng cháng jiàn miàn."],["但是我们经常打电话。","Nhưng chúng tôi thường xuyên gọi điện thoại.","Dàn shì wǒ men jīng cháng dǎ diàn huà."],["我也经常给爸爸妈妈打电话。","Tôi cũng thường gọi điện cho bố mẹ.","Wǒ yě jīng cháng gěi bà ba mā ma dǎ diàn huà."],["听说他们身体很好，我就很高兴。","Nghe nói sức khỏe của bố mẹ đều tốt, tôi rất vui.","Tīng shuō tā men shēn tǐ hěn hǎo, wǒ jiù hěn gāo xìng."],["我很爱我的家人。","Tôi rất yêu gia đình mình.","Wǒ hěn ài wǒ de jiā rén."]],"g":"A"},{"id":3,"q":"你每天几点起床？起床以后做什么？","qvi":"Buổi sáng của bạn","s":[["我每天早上六点起床。","Mỗi sáng tôi thức dậy lúc sáu giờ.","Wǒ měi tiān zǎo shang liù diǎn qǐ chuáng."],["起床以后，我先喝一杯水。","Sau khi thức dậy, trước tiên tôi uống một cốc nước.","Qǐ chuáng yǐ hòu, wǒ xiān hē yì bēi shuǐ."],["然后我出去跑步。","Sau đó tôi ra ngoài chạy bộ.","Rán hòu wǒ chū qù pǎo bù."],["我每天跑步三十分钟。","Mỗi ngày tôi chạy bộ ba mươi phút.","Wǒ měi tiān pǎo bù sān shí fēn zhōng."],["跑步的时候，我喜欢听音乐。","Khi chạy bộ, tôi thích nghe nhạc.","Pǎo bù de shí hou, wǒ xǐ huan tīng yīn yuè."],["运动以后，我就回家。","Sau khi tập thể thao, tôi về nhà.","Yùn dòng yǐ hòu, wǒ jiù huí jiā."],["回家以后，我先洗手。","Về nhà xong, trước tiên tôi rửa tay.","Huí jiā yǐ hòu, wǒ xiān xǐ shǒu."],["然后我开始吃早饭。","Sau đó tôi bắt đầu ăn sáng.","Rán hòu wǒ kāi shǐ chī zǎo fàn."],["我喜欢吃面包，也喜欢喝牛奶。","Tôi thích ăn bánh mì và cũng thích uống sữa.","Wǒ xǐ huan chī miàn bāo, yě xǐ huan hē niú nǎi."],["吃完早饭，我准备去学校。","Ăn sáng xong, tôi chuẩn bị đến trường.","Chī wán zǎo fàn, wǒ zhǔn bèi qù xué xiào."],["我每天八点开始上课。","Mỗi ngày tôi bắt đầu vào học lúc tám giờ.","Wǒ měi tiān bā diǎn kāi shǐ shàng kè."],["我的学校离我家不远。","Trường tôi không xa nhà.","Wǒ de xué xiào lí wǒ jiā bù yuǎn."],["所以我经常走路去学校。","Vì thế tôi thường đi bộ đến trường.","Suǒ yǐ wǒ jīng cháng zǒu lù qù xué xiào."],["到了学校，我就和同学一起上课。","Đến trường, tôi học cùng các bạn trong lớp.","Dào le xué xiào, wǒ jiù hé tóng xué yì qǐ shàng kè."],["我觉得每天早上这样很好。","Tôi thấy buổi sáng mỗi ngày như vậy rất tốt.","Wǒ jué de měi tiān zǎo shang zhè yàng hěn hǎo."]],"g":"B"},{"id":4,"q":"你最喜欢什么季节？为什么？","qvi":"Mùa yêu thích","s":[["我最喜欢夏天。","Tôi thích mùa hè nhất.","Wǒ zuì xǐ huan xià tiān."],["因为我不太喜欢冷天。","Bởi vì tôi không thích trời lạnh lắm.","Yīn wèi wǒ bú tài xǐ huan lěng tiān."],["夏天的天气很热。","Thời tiết mùa hè rất nóng.","Xià tiān de tiān qì hěn rè."],["但是我很喜欢热天。","Nhưng tôi rất thích trời nóng.","Dàn shì wǒ hěn xǐ huan rè tiān."],["天气热的时候，我喜欢出去玩。","Khi trời nóng, tôi thích ra ngoài chơi.","Tiān qì rè de shí hou, wǒ xǐ huan chū qù wán."],["我经常和朋友一起去游泳。","Tôi thường đi bơi cùng bạn bè.","Wǒ jīng cháng hé péng you yì qǐ qù yóu yǒng."],["因为我们都很喜欢游泳。","Bởi vì tất cả chúng tôi đều rất thích bơi.","Yīn wèi wǒ men dōu hěn xǐ huan yóu yǒng."],["我们每个星期去游泳一次。","Mỗi tuần chúng tôi đi bơi một lần.","Wǒ men měi ge xīng qī qù yóu yǒng yí cì."],["游泳以后，我们就去吃饭。","Sau khi bơi, chúng tôi đi ăn cơm.","Yóu yǒng yǐ hòu, wǒ men jiù qù chī fàn."],["我喜欢吃水果。","Tôi thích ăn trái cây.","Wǒ xǐ huan chī shuǐ guǒ."],["我最喜欢吃西瓜。","Tôi thích ăn dưa hấu nhất.","Wǒ zuì xǐ huan chī xī guā."],["因为西瓜很好吃。","Bởi vì dưa hấu rất ngon.","Yīn wèi xī guā hěn hǎo chī."],["下午天气太热的时候，我就在家休息。","Buổi chiều, khi trời quá nóng, tôi nghỉ ngơi ở nhà.","Xià wǔ tiān qì tài rè de shí hou, wǒ jiù zài jiā xiū xī."],["我可以在家看书，也可以听音乐。","Tôi có thể đọc sách ở nhà, cũng có thể nghe nhạc.","Wǒ kě yǐ zài jiā kàn shū, yě kě yǐ tīng yīn yuè."],["所以我觉得夏天很快乐。","Vì vậy tôi thấy mùa hè rất vui.","Suǒ yǐ wǒ jué de xià tiān hěn kuài lè."]],"g":"C"},{"id":5,"q":"你周末一般做什么？","qvi":"Hoạt động cuối tuần","s":[["我每个周末都不上课。","Cuối tuần nào tôi cũng không có lớp.","Wǒ měi ge zhōu mò dōu bù shàng kè."],["所以周末我有很多时间。","Vì vậy cuối tuần tôi có rất nhiều thời gian.","Suǒ yǐ zhōu mò wǒ yǒu hěn duō shí jiān."],["星期六早上，我八点起床。","Sáng thứ Bảy, tôi thức dậy lúc tám giờ.","Xīng qī liù zǎo shang, wǒ bā diǎn qǐ chuáng."],["吃完早饭，我就开始做作业。","Ăn sáng xong, tôi bắt đầu làm bài tập.","Chī wán zǎo fàn, wǒ jiù kāi shǐ zuò zuò yè."],["做完作业以后，我看一会儿汉语书。","Làm bài tập xong, tôi đọc sách tiếng Trung một lát.","Zuò wán zuò yè yǐ hòu, wǒ kàn yí huìr hàn yǔ shū."],["中午我在家吃饭。","Buổi trưa tôi ăn cơm ở nhà.","Zhōng wǔ wǒ zài jiā chī fàn."],["下午我给朋友打电话。","Buổi chiều tôi gọi điện cho bạn.","Xià wǔ wǒ gěi péng you dǎ diàn huà."],["我问他想不想去踢足球。","Tôi hỏi bạn ấy có muốn đi đá bóng không.","Wǒ wèn tā xiǎng bù xiǎng qù tī zú qiú."],["他说他也想去。","Bạn ấy nói cũng muốn đi.","Tā shuō tā yě xiǎng qù."],["所以我们一起去踢足球。","Vì thế chúng tôi cùng đi đá bóng.","Suǒ yǐ wǒ men yì qǐ qù tī zú qiú."],["踢完足球，我们一起吃饭。","Đá bóng xong, chúng tôi đi ăn cùng nhau.","Tī wán zú qiú, wǒ men yì qǐ chī fàn."],["晚上我回家休息。","Buổi tối tôi về nhà nghỉ ngơi.","Wǎn shang wǒ huí jiā xiū xī."],["星期天我经常在家看书。","Chủ Nhật tôi thường đọc sách ở nhà.","Xīng qī tiān wǒ jīng cháng zài jiā kàn shū."],["有时候我也看看电影。","Đôi khi tôi cũng xem phim một chút.","Yǒu shí hou wǒ yě kàn kàn diàn yǐng."],["我觉得这样的周末很快乐。","Tôi cảm thấy cuối tuần như vậy rất vui.","Wǒ jué de zhè yàng de zhōu mò hěn kuài lè."]],"g":"B"},{"id":6,"q":"你每天几点睡觉？睡觉前做什么？","qvi":"Trước khi đi ngủ","s":[["我每天晚上十点睡觉。","Tôi đi ngủ lúc mười giờ tối mỗi ngày.","Wǒ měi tiān wǎn shang shí diǎn shuì jiào."],["因为我第二天要早起。","Bởi vì hôm sau tôi phải dậy sớm.","Yīn wèi wǒ dì èr tiān yào zǎo qǐ."],["我晚上七点吃晚饭。","Tôi ăn tối lúc bảy giờ.","Wǒ wǎn shang qī diǎn chī wǎn fàn."],["吃完饭，我先休息一会儿。","Ăn xong, tôi nghỉ ngơi một lát trước.","Chī wán fàn, wǒ xiān xiū xī yí huìr."],["然后我开始做作业。","Sau đó tôi bắt đầu làm bài tập.","Rán hòu wǒ kāi shǐ zuò zuò yè."],["做完作业以后，我练习写汉字。","Làm bài tập xong, tôi luyện viết chữ Hán.","Zuò wán zuò yè yǐ hòu, wǒ liàn xí xiě hàn zì."],["我也练习说汉语。","Tôi cũng luyện nói tiếng Trung.","Wǒ yě liàn xí shuō hàn yǔ."],["学习一个小时以后，我就休息。","Sau khi học một tiếng, tôi nghỉ ngơi.","Xué xí yí ge xiǎo shí yǐ hòu, wǒ jiù xiū xī."],["有时候我看一会儿电视。","Đôi khi tôi xem tivi một lát.","Yǒu shí hou wǒ kàn yí huìr diàn shì."],["有时候我听音乐。","Đôi khi tôi nghe nhạc.","Yǒu shí hou wǒ tīng yīn yuè."],["九点的时候，我给妈妈打电话。","Lúc chín giờ tôi gọi điện cho mẹ.","Jiǔ diǎn de shí hou, wǒ gěi mā ma dǎ diàn huà."],["我问她今天工作累不累。","Tôi hỏi mẹ hôm nay đi làm có mệt không.","Wǒ wèn tā jīn tiān gōng zuò lèi bù lèi."],["和妈妈说完话，我就准备睡觉。","Nói chuyện với mẹ xong, tôi chuẩn bị đi ngủ.","Hé mā ma shuō wán huà, wǒ jiù zhǔn bèi shuì jiào."],["十点我已经在床上了。","Mười giờ tôi đã ở trên giường rồi.","Shí diǎn wǒ yǐ jīng zài chuáng shàng le."],["我觉得每天早点睡觉很好。","Tôi thấy đi ngủ sớm một chút mỗi ngày rất tốt.","Wǒ jué de měi tiān zǎo diǎn shuì jiào hěn hǎo."]],"g":"B"},{"id":7,"q":"你觉得学习汉语最难的是什么？","qvi":"Khó khăn khi học tiếng Trung","s":[["我已经学习汉语三个月了。","Tôi đã học tiếng Trung được ba tháng rồi.","Wǒ yǐ jīng xué xí hàn yǔ sān ge yuè le."],["我很喜欢学习汉语。","Tôi rất thích học tiếng Trung.","Wǒ hěn xǐ huan xué xí hàn yǔ."],["但是我觉得写汉字最难。","Nhưng tôi cảm thấy viết chữ Hán là khó nhất.","Dàn shì wǒ jué de xiě hàn zì zuì nán."],["因为有很多汉字我不认识。","Bởi vì có rất nhiều chữ Hán tôi không biết.","Yīn wèi yǒu hěn duō hàn zì wǒ bú rèn shi."],["有时候老师让我写字。","Đôi khi giáo viên bảo tôi viết chữ.","Yǒu shí hou lǎo shī ràng wǒ xiě zì."],["我写了很多字，但是还有错的。","Tôi viết rất nhiều chữ nhưng vẫn có chữ sai.","Wǒ xiě le hěn duō zì, dàn shì hái yǒu cuò de."],["所以我每天都练习写汉字。","Vì vậy ngày nào tôi cũng luyện viết chữ Hán.","Suǒ yǐ wǒ měi tiān dōu liàn xí xiě hàn zì."],["我每天写十个汉字。","Mỗi ngày tôi viết mười chữ Hán.","Wǒ měi tiān xiě shí ge hàn zì."],["写完字以后，我再看汉语书。","Viết xong, tôi lại đọc sách tiếng Trung.","Xiě wán zì yǐ hòu, wǒ zài kàn hàn yǔ shū."],["有不认识的字，我就问老师。","Nếu có chữ không biết, tôi hỏi giáo viên.","Yǒu bú rèn shi de zì, wǒ jiù wèn lǎo shī."],["老师会帮助我。","Giáo viên sẽ giúp tôi.","Lǎo shī huì bāng zhù wǒ."],["我也经常和同学一起练习。","Tôi cũng thường xuyên luyện tập cùng bạn học.","Wǒ yě jīng cháng hé tóng xué yì qǐ liàn xí."],["现在我已经认识很多汉字了。","Bây giờ tôi đã biết rất nhiều chữ Hán rồi.","Xiàn zài wǒ yǐ jīng rèn shi hěn duō hàn zì le."],["我觉得每天练习很重要。","Tôi thấy luyện tập mỗi ngày rất quan trọng.","Wǒ jué de měi tiān liàn xí hěn zhòng yào."],["我想写好汉字。","Tôi muốn viết chữ Hán thật tốt.","Wǒ xiǎng xiě hǎo hàn zì."]],"g":"D"},{"id":8,"q":"你会做饭吗？你最会做什么菜？","qvi":"Khả năng nấu ăn","s":[["我会做饭。","Tôi biết nấu ăn.","Wǒ huì zuò fàn."],["我很喜欢在家做饭。","Tôi rất thích nấu ăn ở nhà.","Wǒ hěn xǐ huan zài jiā zuò fàn."],["我最会做鱼。","Món tôi nấu giỏi nhất là cá.","Wǒ zuì huì zuò yú."],["因为我很喜欢吃鱼。","Bởi vì tôi rất thích ăn cá.","Yīn wèi wǒ hěn xǐ huan chī yú."],["周末我经常自己做饭。","Cuối tuần tôi thường tự nấu ăn.","Zhōu mò wǒ jīng cháng zì jǐ zuò fàn."],["做饭以前，我先去超市买菜。","Trước khi nấu, tôi đến siêu thị mua thực phẩm.","Zuò fàn yǐ qián, wǒ xiān qù chāo shì mǎi cài."],["我买鱼，也买一些青菜。","Tôi mua cá và một ít rau xanh.","Wǒ mǎi yú, yě mǎi yì xiē qīng cài."],["买完菜以后，我就回家。","Mua rau xong, tôi về nhà.","Mǎi wán cài yǐ hòu, wǒ jiù huí jiā."],["回家以后，我先洗手。","Về nhà, tôi rửa tay trước.","Huí jiā yǐ hòu, wǒ xiān xǐ shǒu."],["然后我开始做菜。","Sau đó tôi bắt đầu nấu các món ăn.","Rán hòu wǒ kāi shǐ zuò cài."],["我会做鱼，也会做米饭。","Tôi biết nấu cá và cũng biết nấu cơm.","Wǒ huì zuò yú, yě huì zuò mǐ fàn."],["做完饭，我就请家人一起吃。","Nấu xong, tôi mời gia đình cùng ăn.","Zuò wán fàn, wǒ jiù qǐng jiā rén yì qǐ chī."],["妈妈说我做的鱼很好吃。","Mẹ nói món cá tôi nấu rất ngon.","Mā ma shuō wǒ zuò de yú hěn hǎo chī."],["听了妈妈的话，我很高兴。","Nghe mẹ nói thế, tôi rất vui.","Tīng le mā ma de huà, wǒ hěn gāo xìng."],["所以我还想学习做更多的菜。","Vì vậy tôi còn muốn học nấu nhiều món hơn.","Suǒ yǐ wǒ hái xiǎng xué xí zuò gèng duō de cài."]],"g":"E"},{"id":9,"q":"如果你有钱，你想买什么？","qvi":"Nếu có tiền, bạn sẽ mua gì?","s":[["如果我有很多钱，我想买一台新电脑。","Nếu có nhiều tiền, tôi muốn mua một chiếc máy tính mới.","Rú guǒ wǒ yǒu hěn duō qián, wǒ xiǎng mǎi yì tái xīn diàn nǎo."],["因为我很喜欢电脑。","Bởi vì tôi rất thích máy tính.","Yīn wèi wǒ hěn xǐ huan diàn nǎo."],["我以前在大学学习信息技术。","Trước đây tôi học công nghệ thông tin ở đại học.","Wǒ yǐ qián zài dà xué xué xí xìn xī jì shù."],["所以电脑对我很重要。","Vì vậy máy tính rất quan trọng đối với tôi.","Suǒ yǐ diàn nǎo duì wǒ hěn zhòng yào."],["我现在有一台电脑。","Hiện tại tôi có một chiếc máy tính.","Wǒ xiàn zài yǒu yì tái diàn nǎo."],["但是我的电脑已经很老了。","Nhưng máy tính của tôi đã rất cũ.","Dàn shì wǒ de diàn nǎo yǐ jīng hěn lǎo le."],["有时候我用电脑做作业。","Đôi khi tôi dùng máy tính làm bài tập.","Yǒu shí hou wǒ yòng diàn nǎo zuò zuò yè."],["有时候电脑有问题。","Đôi khi máy tính gặp vấn đề.","Yǒu shí hou diàn nǎo yǒu wèn tí."],["所以我想买一台新的。","Vì vậy tôi muốn mua một chiếc mới.","Suǒ yǐ wǒ xiǎng mǎi yì tái xīn de."],["我也想用新电脑学习汉语。","Tôi cũng muốn dùng máy tính mới để học tiếng Trung.","Wǒ yě xiǎng yòng xīn diàn nǎo xué xí hàn yǔ."],["我可以在电脑上看汉语电影。","Tôi có thể xem phim tiếng Trung trên máy tính.","Wǒ kě yǐ zài diàn nǎo shang kàn hàn yǔ diàn yǐng."],["我还可以用电脑和朋友说话。","Tôi còn có thể dùng máy tính nói chuyện với bạn bè.","Wǒ hái kě yǐ yòng diàn nǎo hé péng you shuō huà."],["但是新电脑很贵。","Nhưng máy tính mới rất đắt.","Dàn shì xīn diàn nǎo hěn guì."],["所以我现在不准备买。","Vì vậy hiện tại tôi chưa định mua.","Suǒ yǐ wǒ xiàn zài bù zhǔn bèi mǎi."],["有了钱以后，我就去买新电脑。","Sau khi có tiền, tôi sẽ đi mua máy tính mới.","Yǒu le qián yǐ hòu, wǒ jiù qù mǎi xīn diàn nǎo."]],"g":"H"},{"id":10,"q":"你喜欢一个人出去玩还是和朋友一起出去玩？为什么？","qvi":"Đi chơi một mình hay cùng bạn bè?","s":[["我很喜欢出去玩。","Tôi rất thích ra ngoài chơi.","Wǒ hěn xǐ huan chū qù wán."],["但是我不太喜欢一个人出去玩。","Nhưng tôi không thích đi chơi một mình lắm.","Dàn shì wǒ bú tài xǐ huan yí ge rén chū qù wán."],["我更喜欢和朋友一起出去玩。","Tôi thích đi chơi với bạn bè hơn.","Wǒ gèng xǐ huan hé péng you yì qǐ chū qù wán."],["因为我有几个好朋友。","Bởi vì tôi có vài người bạn tốt.","Yīn wèi wǒ yǒu jǐ ge hǎo péng you."],["他们以前都是我的同学。","Trước đây họ đều là bạn học của tôi.","Tā men yǐ qián dōu shì wǒ de tóng xué."],["我们经常打电话。","Chúng tôi thường xuyên gọi điện thoại.","Wǒ men jīng cháng dǎ diàn huà."],["周末我们都有空儿。","Cuối tuần chúng tôi đều rảnh.","Zhōu mò wǒ men dōu yǒu kòngr."],["所以我们经常一起出去玩。","Vì thế chúng tôi thường đi chơi cùng nhau.","Suǒ yǐ wǒ men jīng cháng yì qǐ chū qù wán."],["我们最喜欢一起踢足球。","Chúng tôi thích đá bóng cùng nhau nhất.","Wǒ men zuì xǐ huan yì qǐ tī zú qiú."],["有时候我们也一起看电影。","Đôi khi chúng tôi cũng cùng xem phim.","Yǒu shí hou wǒ men yě yì qǐ kàn diàn yǐng."],["看完电影以后，我们一起吃饭。","Xem phim xong, chúng tôi cùng đi ăn.","Kàn wán diàn yǐng yǐ hòu, wǒ men yì qǐ chī fàn."],["吃饭的时候，我们经常说话。","Trong lúc ăn, chúng tôi thường trò chuyện.","Chī fàn de shí hou, wǒ men jīng cháng shuō huà."],["和朋友在一起，我觉得很快乐。","Ở bên bạn bè, tôi cảm thấy rất vui.","Hé péng you zài yì qǐ, wǒ jué de hěn kuài lè."],["一个人出去玩没有那么有意思。","Đi chơi một mình không thú vị đến thế.","Yí ge rén chū qù wán méi yǒu nà me yǒu yì sī."],["所以我更喜欢和朋友一起出去玩。","Vì vậy tôi thích đi chơi với bạn bè hơn.","Suǒ yǐ wǒ gèng xǐ huan hé péng you yì qǐ chū qù wán."]],"g":"C"},{"id":11,"q":"你觉得工作和学习哪个更重要？为什么？","qvi":"Công việc và học tập","s":[["我觉得工作和学习都很重要。","Tôi nghĩ công việc và học tập đều rất quan trọng.","Wǒ jué de gōng zuò hé xué xí dōu hěn zhòng yào."],["但是现在我觉得学习更重要。","Nhưng hiện tại tôi thấy việc học quan trọng hơn.","Dàn shì xiàn zài wǒ jué de xué xí gèng zhòng yào."],["因为我现在正在学习汉语。","Bởi vì hiện tại tôi đang học tiếng Trung.","Yīn wèi wǒ xiàn zài zhèng zài xué xí hàn yǔ."],["我每天都要上课。","Mỗi ngày tôi đều phải lên lớp.","Wǒ měi tiān dōu yào shàng kè."],["上课的时候，我好好听老师说话。","Trong giờ học, tôi chăm chú nghe giáo viên nói.","Shàng kè de shí hou, wǒ hǎo hǎo tīng lǎo shī shuō huà."],["下课以后，我回家做作业。","Sau khi tan học, tôi về nhà làm bài tập.","Xià kè yǐ hòu, wǒ huí jiā zuò zuò yè."],["有时候我觉得汉语很难。","Đôi khi tôi cảm thấy tiếng Trung rất khó.","Yǒu shí hou wǒ jué de hàn yǔ hěn nán."],["但是我还是每天都学习。","Nhưng tôi vẫn học mỗi ngày.","Dàn shì wǒ hái shì měi tiān dōu xué xí."],["因为我想说好汉语。","Bởi vì tôi muốn nói tốt tiếng Trung.","Yīn wèi wǒ xiǎng shuō hǎo hàn yǔ."],["我以前在大学学习信息技术。","Trước đây tôi học công nghệ thông tin ở đại học.","Wǒ yǐ qián zài dà xué xué xí xìn xī jì shù."],["我也很喜欢这个专业。","Tôi cũng rất thích chuyên ngành này.","Wǒ yě hěn xǐ huan zhè ge zhuān yè."],["以后我想在公司工作。","Sau này tôi muốn làm việc ở công ty.","Yǐ hòu wǒ xiǎng zài gōng sī gōng zuò."],["如果我会说汉语，工作就更方便。","Nếu tôi biết nói tiếng Trung, công việc sẽ thuận tiện hơn.","Rú guǒ wǒ huì shuō hàn yǔ, gōng zuò jiù gèng fāng biàn."],["所以我现在要好好学习。","Vì vậy hiện tại tôi cần học thật tốt.","Suǒ yǐ wǒ xiàn zài yào hǎo hǎo xué xí."],["学好了汉语，我再去找工作。","Học tốt tiếng Trung rồi, tôi mới đi tìm việc.","Xué hǎo le hàn yǔ, wǒ zài qù zhǎo gōng zuò."]],"g":"D"},{"id":12,"q":"请说一下让你高兴的一件事。","qvi":"Một việc khiến bạn vui","s":[["上个星期天是妈妈的生日。","Chủ Nhật tuần trước là sinh nhật mẹ tôi.","Shàng ge xīng qī tiān shì mā ma de shēng rì."],["那天我很高兴。","Hôm đó tôi rất vui.","Nà tiān wǒ hěn gāo xìng."],["因为我想给妈妈买一件礼物。","Bởi vì tôi muốn mua một món quà cho mẹ.","Yīn wèi wǒ xiǎng gěi mā ma mǎi yí jiàn lǐ wù."],["我知道妈妈很喜欢红色。","Tôi biết mẹ rất thích màu đỏ.","Wǒ zhī dào mā ma hěn xǐ huan hóng sè."],["所以我去商店看红色的衣服。","Vì vậy tôi đến cửa hàng xem quần áo màu đỏ.","Suǒ yǐ wǒ qù shāng diàn kàn hóng sè de yī fu."],["商店里有很多漂亮的衣服。","Trong cửa hàng có rất nhiều quần áo đẹp.","Shāng diàn lǐ yǒu hěn duō piào liang de yī fu."],["我买了一件红色的衣服。","Tôi mua một chiếc áo màu đỏ.","Wǒ mǎi le yí jiàn hóng sè de yī fu."],["买完以后，我就回家。","Mua xong, tôi về nhà.","Mǎi wán yǐ hòu, wǒ jiù huí jiā."],["到了家，我对妈妈说生日快乐。","Về đến nhà, tôi nói với mẹ: Chúc mừng sinh nhật.","Dào le jiā, wǒ duì mā ma shuō shēng rì kuài lè."],["然后我送给妈妈这件衣服。","Sau đó tôi tặng mẹ chiếc áo này.","Rán hòu wǒ sòng gěi mā ma zhè jiàn yī fu."],["妈妈看见衣服很高兴。","Mẹ nhìn thấy chiếc áo thì rất vui.","Mā ma kàn jiàn yī fu hěn gāo xìng."],["她说这件衣服很漂亮。","Mẹ nói chiếc áo này rất đẹp.","Tā shuō zhè jiàn yī fu hěn piào liang."],["晚上我们一家人一起吃饭。","Buổi tối cả gia đình tôi cùng ăn cơm.","Wǎn shang wǒ men yī jiā rén yì qǐ chī fàn."],["吃饭的时候，大家都很高兴。","Trong bữa ăn, mọi người đều rất vui.","Chī fàn de shí hou, dà jiā dōu hěn gāo xìng."],["这是让我很高兴的一件事。","Đó là một việc khiến tôi rất vui.","Zhè shì ràng wǒ hěn gāo xìng de yí jiàn shì."]],"g":"G"},{"id":13,"q":"你喜欢什么运动？为什么？","qvi":"Môn thể thao yêu thích","s":[["我很喜欢运动。","Tôi rất thích thể thao.","Wǒ hěn xǐ huan yùn dòng."],["我最喜欢踢足球。","Tôi thích đá bóng nhất.","Wǒ zuì xǐ huan tī zú qiú."],["因为我觉得踢足球很有意思。","Bởi vì tôi thấy đá bóng rất thú vị.","Yīn wèi wǒ jué de tī zú qiú hěn yǒu yì sī."],["我的几个好朋友也喜欢踢足球。","Vài người bạn tốt của tôi cũng thích đá bóng.","Wǒ de jǐ ge hǎo péng you yě xǐ huan tī zú qiú."],["所以我们经常一起踢足球。","Vì vậy chúng tôi thường đá bóng cùng nhau.","Suǒ yǐ wǒ men jīng cháng yì qǐ tī zú qiú."],["我们一般下午六点开始踢。","Chúng tôi thường bắt đầu đá lúc sáu giờ chiều.","Wǒ men yī bān xià wǔ liù diǎn kāi shǐ tī."],["我们每次踢一个小时。","Mỗi lần chúng tôi đá một tiếng.","Wǒ men měi cì tī yí ge xiǎo shí."],["踢足球的时候，我很高兴。","Khi đá bóng, tôi rất vui.","Tī zú qiú de shí hou, wǒ hěn gāo xìng."],["有时候我踢得不太好。","Đôi khi tôi đá không được tốt lắm.","Yǒu shí hou wǒ tī de bú tài hǎo."],["朋友就来帮助我。","Bạn bè liền đến giúp tôi.","Péng you jiù lái bāng zhù wǒ."],["踢完足球以后，我们都很累。","Sau khi đá bóng, tất cả chúng tôi đều rất mệt.","Tī wán zú qiú yǐ hòu, wǒ men dōu hěn lèi."],["但是大家都很快乐。","Nhưng mọi người đều rất vui.","Dàn shì dà jiā dōu hěn kuài lè."],["我们一起喝水，再休息一会儿。","Chúng tôi cùng uống nước rồi nghỉ ngơi một lát.","Wǒ men yì qǐ hē shuǐ, zài xiū xī yí huìr."],["我觉得踢足球对身体很好。","Tôi thấy đá bóng rất tốt cho sức khỏe.","Wǒ jué de tī zú qiú duì shēn tǐ hěn hǎo."],["所以我每个星期都想踢足球。","Vì vậy tuần nào tôi cũng muốn đá bóng.","Suǒ yǐ wǒ měi ge xīng qī dōu xiǎng tī zú qiú."]],"g":"C"},{"id":14,"q":"妈妈有时候会让你帮她做什么？","qvi":"Giúp mẹ làm việc nhà","s":[["我妈妈每天都很忙。","Mẹ tôi mỗi ngày đều rất bận.","Wǒ mā ma měi tiān dōu hěn máng."],["她每天都要做饭。","Mỗi ngày mẹ đều phải nấu ăn.","Tā měi tiān dōu yào zuò fàn."],["所以有时候她让我帮她做家务。","Vì vậy đôi khi mẹ nhờ tôi giúp làm việc nhà.","Suǒ yǐ yǒu shí hou tā ràng wǒ bāng tā zuò jiā wù."],["星期天我经常在家。","Chủ Nhật tôi thường ở nhà.","Xīng qī tiān wǒ jīng cháng zài jiā."],["妈妈先让我去超市买菜。","Đầu tiên mẹ nhờ tôi đến siêu thị mua thực phẩm.","Mā ma xiān ràng wǒ qù chāo shì mǎi cài."],["我买一些鱼和青菜。","Tôi mua một ít cá và rau xanh.","Wǒ mǎi yì xiē yú hé qīng cài."],["有时候我还买一些水果。","Đôi khi tôi còn mua một ít trái cây.","Yǒu shí hou wǒ hái mǎi yì xiē shuǐ guǒ."],["买完东西以后，我就回家。","Mua đồ xong, tôi về nhà.","Mǎi wán dōng xi yǐ hòu, wǒ jiù huí jiā."],["回家以后，我帮助妈妈做饭。","Về nhà, tôi giúp mẹ nấu ăn.","Huí jiā yǐ hòu, wǒ bāng zhù mā ma zuò fàn."],["妈妈做鱼，我做米饭。","Mẹ nấu cá, tôi nấu cơm.","Mā ma zuò yú, wǒ zuò mǐ fàn."],["做完饭，我们一家人一起吃。","Nấu xong, cả gia đình cùng ăn.","Zuò wán fàn, wǒ men yī jiā rén yì qǐ chī."],["吃完饭，我帮助妈妈洗碗。","Ăn xong, tôi giúp mẹ rửa bát.","Chī wán fàn, wǒ bāng zhù mā ma xǐ wǎn."],["妈妈说我做得很好。","Mẹ nói tôi làm rất tốt.","Mā ma shuō wǒ zuò de hěn hǎo."],["听了妈妈的话，我很高兴。","Nghe mẹ nói thế, tôi rất vui.","Tīng le mā ma de huà, wǒ hěn gāo xìng."],["以后我还想经常帮助妈妈。","Sau này tôi vẫn muốn thường xuyên giúp mẹ.","Yǐ hòu wǒ hái xiǎng jīng cháng bāng zhù mā ma."]],"g":"E"},{"id":15,"q":"你每天是怎么保持健康？","qvi":"Giữ gìn sức khỏe","s":[["我觉得身体好很重要。","Tôi nghĩ sức khỏe tốt rất quan trọng.","Wǒ jué de shēn tǐ hǎo hěn zhòng yào."],["所以我每天都运动。","Vì vậy ngày nào tôi cũng tập thể thao.","Suǒ yǐ wǒ měi tiān dōu yùn dòng."],["我早上六点起床。","Tôi thức dậy lúc sáu giờ sáng.","Wǒ zǎo shang liù diǎn qǐ chuáng."],["起床以后，我先喝水。","Sau khi dậy, trước tiên tôi uống nước.","Qǐ chuáng yǐ hòu, wǒ xiān hē shuǐ."],["然后我去外面跑步。","Sau đó tôi ra ngoài chạy bộ.","Rán hòu wǒ qù wài miàn pǎo bù."],["我每天跑步三十分钟。","Mỗi ngày tôi chạy bộ ba mươi phút.","Wǒ měi tiān pǎo bù sān shí fēn zhōng."],["运动以后，我就回家吃早饭。","Tập thể thao xong, tôi về nhà ăn sáng.","Yùn dòng yǐ hòu, wǒ jiù huí jiā chī zǎo fàn."],["我喜欢吃面包和水果。","Tôi thích ăn bánh mì và trái cây.","Wǒ xǐ huan chī miàn bāo hé shuǐ guǒ."],["我也喜欢喝牛奶。","Tôi cũng thích uống sữa.","Wǒ yě xǐ huan hē niú nǎi."],["中午我经常吃米饭和青菜。","Buổi trưa tôi thường ăn cơm và rau xanh.","Zhōng wǔ wǒ jīng cháng chī mǐ fàn hé qīng cài."],["下午有空儿的时候，我就踢足球。","Buổi chiều lúc rảnh, tôi đi đá bóng.","Xià wǔ yǒu kòngr de shí hou, wǒ jiù tī zú qiú."],["运动以后，我会休息一会儿。","Tập thể thao xong, tôi nghỉ ngơi một lát.","Yùn dòng yǐ hòu, wǒ huì xiū xī yí huìr."],["晚上我不喝太多咖啡。","Buổi tối tôi không uống quá nhiều cà phê.","Wǎn shang wǒ bù hē tài duō kā fēi."],["我每天十点就睡觉。","Mỗi ngày mười giờ tôi đi ngủ.","Wǒ měi tiān shí diǎn jiù shuì jiào."],["我觉得这样对身体很好。","Tôi nghĩ như vậy rất tốt cho sức khỏe.","Wǒ jué de zhè yàng duì shēn tǐ hěn hǎo."]],"g":"F"},{"id":16,"q":"你觉得早睡早起对身体好吗？","qvi":"Ngủ sớm dậy sớm","s":[["我觉得早睡早起对身体很好。","Tôi nghĩ ngủ sớm dậy sớm rất tốt cho sức khỏe.","Wǒ jué de zǎo shuì zǎo qǐ duì shēn tǐ hěn hǎo."],["我每天晚上十点睡觉。","Mỗi ngày tôi đi ngủ lúc mười giờ tối.","Wǒ měi tiān wǎn shang shí diǎn shuì jiào."],["因为第二天我要六点起床。","Bởi vì hôm sau tôi phải dậy lúc sáu giờ.","Yīn wèi dì èr tiān wǒ yào liù diǎn qǐ chuáng."],["以前我有时候睡得很晚。","Trước đây đôi khi tôi ngủ rất muộn.","Yǐ qián wǒ yǒu shí hou shuì de hěn wǎn."],["第二天上课的时候，我觉得很累。","Hôm sau khi lên lớp, tôi cảm thấy rất mệt.","Dì èr tiān shàng kè de shí hou, wǒ jué de hěn lèi."],["后来我开始早点睡觉。","Sau đó tôi bắt đầu ngủ sớm hơn.","Hòu lái wǒ kāi shǐ zǎo diǎn shuì jiào."],["现在我每天都早睡早起。","Bây giờ ngày nào tôi cũng ngủ sớm dậy sớm.","Xiàn zài wǒ měi tiān dōu zǎo shuì zǎo qǐ."],["早上起床以后，我先喝水。","Sau khi thức dậy, trước tiên tôi uống nước.","Zǎo shang qǐ chuáng yǐ hòu, wǒ xiān hē shuǐ."],["然后我去跑步。","Sau đó tôi đi chạy bộ.","Rán hòu wǒ qù pǎo bù."],["运动以后，我回家吃早饭。","Tập thể thao xong, tôi về nhà ăn sáng.","Yùn dòng yǐ hòu, wǒ huí jiā chī zǎo fàn."],["吃完早饭，我就去学校。","Ăn sáng xong, tôi đến trường.","Chī wán zǎo fàn, wǒ jiù qù xué xiào."],["因为睡得早，所以上课的时候我不太累。","Vì ngủ sớm nên khi lên lớp tôi không mệt lắm.","Yīn wèi shuì de zǎo, suǒ yǐ shàng kè de shí hou wǒ bú tài lèi."],["下午我还有时间运动。","Buổi chiều tôi còn có thời gian chơi thể thao.","Xià wǔ wǒ hái yǒu shí jiān yùn dòng."],["晚上我也有时间做作业。","Buổi tối tôi cũng có thời gian làm bài tập.","Wǎn shang wǒ yě yǒu shí jiān zuò zuò yè."],["所以我想每天都早睡早起。","Vì vậy tôi muốn ngủ sớm dậy sớm mỗi ngày.","Suǒ yǐ wǒ xiǎng měi tiān dōu zǎo shuì zǎo qǐ."]],"g":"F"},{"id":17,"q":"给你三天时间，你会做什么？","qvi":"Nếu có ba ngày rảnh","s":[["如果我有三天时间，我想去北京旅游。","Nếu có ba ngày, tôi muốn đi du lịch Bắc Kinh.","Rú guǒ wǒ yǒu sān tiān shí jiān, wǒ xiǎng qù Běi jīng lǚ yóu."],["因为我很想去中国看看。","Bởi vì tôi rất muốn đến Trung Quốc tham quan.","Yīn wèi wǒ hěn xiǎng qù Zhōng guó kàn kàn."],["第一天，我准备坐飞机去北京。","Ngày đầu tiên tôi định đi máy bay đến Bắc Kinh.","Dì yì tiān, wǒ zhǔn bèi zuò fēi jī qù Běi jīng."],["到了北京以后，我先去饭馆吃饭。","Đến Bắc Kinh, trước tiên tôi tới quán ăn ăn cơm.","Dào le Běi jīng yǐ hòu, wǒ xiān qù fàn guǎn chī fàn."],["我想吃中国的饺子。","Tôi muốn ăn sủi cảo Trung Quốc.","Wǒ xiǎng chī Zhōng guó de jiǎo zi."],["吃完饭，我在附近走一走。","Ăn xong, tôi đi dạo một chút ở gần đó.","Chī wán fàn, wǒ zài fù jìn zǒu yī zǒu."],["第二天，我想去看北京的风景。","Ngày thứ hai, tôi muốn đi ngắm cảnh Bắc Kinh.","Dì èr tiān, wǒ xiǎng qù kàn Běi jīng de fēng jǐng."],["我也想拍很多照片。","Tôi cũng muốn chụp rất nhiều ảnh.","Wǒ yě xiǎng pāi hěn duō zhào piàn."],["下午我去商店买一些东西。","Buổi chiều tôi đến cửa hàng mua một ít đồ.","Xià wǔ wǒ qù shāng diàn mǎi yì xiē dōng xi."],["晚上我想和中国朋友一起吃饭。","Buổi tối tôi muốn ăn cơm cùng bạn Trung Quốc.","Wǎn shang wǒ xiǎng hé Zhōng guó péng you yì qǐ chī fàn."],["第三天，我准备回家。","Ngày thứ ba tôi chuẩn bị về nhà.","Dì sān tiān, wǒ zhǔn bèi huí jiā."],["回家以前，我想再吃一次中国菜。","Trước khi về, tôi muốn ăn món Trung Quốc thêm một lần nữa.","Huí jiā yǐ qián, wǒ xiǎng zài chī yí cì Zhōng guó cài."],["然后我坐飞机回越南。","Sau đó tôi đi máy bay về Việt Nam.","Rán hòu wǒ zuò fēi jī huí Yuè nán."],["回家以后，我给家人看照片。","Về nhà, tôi cho gia đình xem ảnh.","Huí jiā yǐ hòu, wǒ gěi jiā rén kàn zhào piàn."],["我觉得这三天会很快乐。","Tôi nghĩ ba ngày đó sẽ rất vui.","Wǒ jué de zhè sān tiān huì hěn kuài lè."]],"g":"H"},{"id":18,"q":"你以后想做什么工作？","qvi":"Công việc tương lai","s":[["我以后想在信息技术公司工作。","Sau này tôi muốn làm việc tại một công ty công nghệ thông tin.","Wǒ yǐ hòu xiǎng zài xìn xī jì shù gōng sī gōng zuò."],["因为我很喜欢电脑。","Bởi vì tôi rất thích máy tính.","Yīn wèi wǒ hěn xǐ huan diàn nǎo."],["我以前在莫斯科上大学。","Trước đây tôi học đại học ở Moscow.","Wǒ yǐ qián zài Mò sī kē shàng dà xué."],["我的专业是信息技术。","Chuyên ngành của tôi là công nghệ thông tin.","Wǒ de zhuān yè shì xìn xī jì shù."],["在大学的时候，我每天都学习。","Khi học đại học, ngày nào tôi cũng học.","Zài dà xué de shí hou, wǒ měi tiān dōu xué xí."],["我也经常用电脑做作业。","Tôi cũng thường xuyên dùng máy tính làm bài tập.","Wǒ yě jīng cháng yòng diàn nǎo zuò zuò yè."],["我觉得这个专业很有意思。","Tôi cảm thấy chuyên ngành này rất thú vị.","Wǒ jué de zhè ge zhuān yè hěn yǒu yì sī."],["所以我想找这个专业的工作。","Vì vậy tôi muốn tìm một công việc trong chuyên ngành này.","Suǒ yǐ wǒ xiǎng zhǎo zhè ge zhuān yè de gōng zuò."],["我还想在中国公司工作。","Tôi còn muốn làm việc tại công ty Trung Quốc.","Wǒ hái xiǎng zài Zhōng guó gōng sī gōng zuò."],["因为我现在正在学习汉语。","Bởi vì hiện tại tôi đang học tiếng Trung.","Yīn wèi wǒ xiàn zài zhèng zài xué xí hàn yǔ."],["我想和中国同事一起工作。","Tôi muốn làm việc cùng các đồng nghiệp Trung Quốc.","Wǒ xiǎng hé Zhōng guó tóng shì yì qǐ gōng zuò."],["上班的时候，我们可以说汉语。","Khi đi làm, chúng tôi có thể nói tiếng Trung.","Shàng bān de shí hou, wǒ men kě yǐ shuō hàn yǔ."],["有不懂的问题，我可以问同事。","Nếu có vấn đề không hiểu, tôi có thể hỏi đồng nghiệp.","Yǒu bù dǒng de wèn tí, wǒ kě yǐ wèn tóng shì."],["我想每天好好工作。","Tôi muốn làm việc chăm chỉ mỗi ngày.","Wǒ xiǎng měi tiān hǎo hǎo gōng zuò."],["我觉得这是一份很好的工作。","Tôi thấy đây là một công việc rất tốt.","Wǒ jué de zhè shì yí fèn hěn hǎo de gōng zuò."]],"g":"D"},{"id":19,"q":"你喜欢看书吗？你喜欢看什么书？","qvi":"Sở thích đọc sách","s":[["我很喜欢看书。","Tôi rất thích đọc sách.","Wǒ hěn xǐ huan kàn shū."],["我最喜欢看汉语书。","Tôi thích đọc sách tiếng Trung nhất.","Wǒ zuì xǐ huan kàn hàn yǔ shū."],["因为我现在正在学习汉语。","Bởi vì hiện tại tôi đang học tiếng Trung.","Yīn wèi wǒ xiàn zài zhèng zài xué xí hàn yǔ."],["我的桌子上有很多汉语书。","Trên bàn của tôi có rất nhiều sách tiếng Trung.","Wǒ de zhuō zi shang yǒu hěn duō hàn yǔ shū."],["这些书有的是老师给我的。","Trong số sách này, có cuốn là giáo viên cho tôi.","Zhè xiē shū yǒu de shì lǎo shī gěi wǒ de."],["有的是我自己买的。","Có cuốn tôi tự mua.","Yǒu de shì wǒ zì jǐ mǎi de."],["我每天晚上都看书。","Tối nào tôi cũng đọc sách.","Wǒ měi tiān wǎn shang dōu kàn shū."],["我一般看一个小时。","Tôi thường đọc trong một tiếng.","Wǒ yī bān kàn yí ge xiǎo shí."],["看书的时候，我经常看见新汉字。","Khi đọc sách, tôi thường nhìn thấy chữ Hán mới.","Kàn shū de shí hou, wǒ jīng cháng kàn jiàn xīn hàn zì."],["有的字我还不认识。","Có những chữ tôi vẫn chưa biết.","Yǒu de zì wǒ hái bú rèn shi."],["我就用笔写这个字。","Tôi dùng bút viết lại chữ đó.","Wǒ jiù yòng bǐ xiě zhè ge zì."],["第二天我再问老师。","Ngày hôm sau tôi lại hỏi giáo viên.","Dì èr tiān wǒ zài wèn lǎo shī."],["有时候我也去图书馆看书。","Đôi khi tôi cũng đến thư viện đọc sách.","Yǒu shí hou wǒ yě qù tú shū guǎn kàn shū."],["我觉得看书对学习汉语很有帮助。","Tôi thấy đọc sách rất có ích cho việc học tiếng Trung.","Wǒ jué de kàn shū duì xué xí hàn yǔ hěn yǒu bāng zhù."],["所以我想每天都看书。","Vì vậy tôi muốn đọc sách mỗi ngày.","Suǒ yǐ wǒ xiǎng měi tiān dōu kàn shū."]],"g":"C"},{"id":20,"q":"你最喜欢的颜色是什么？","qvi":"Màu sắc yêu thích","s":[["我最喜欢蓝色。","Tôi thích màu xanh dương nhất.","Wǒ zuì xǐ huan lán sè."],["因为我觉得蓝色很好看。","Bởi vì tôi thấy màu xanh dương rất đẹp.","Yīn wèi wǒ jué de lán sè hěn hǎo kàn."],["我有很多蓝色的东西。","Tôi có nhiều đồ vật màu xanh dương.","Wǒ yǒu hěn duō lán sè de dōng xi."],["我的书包就是蓝色的。","Ba lô của tôi chính là màu xanh dương.","Wǒ de shū bāo jiù shì lán sè de."],["我每天都用这个书包。","Tôi dùng chiếc ba lô này mỗi ngày.","Wǒ měi tiān dōu yòng zhè ge shū bāo."],["我还有一件蓝色的衣服。","Tôi còn có một chiếc áo màu xanh dương.","Wǒ hái yǒu yí jiàn lán sè de yī fu."],["这件衣服是去年买的。","Chiếc áo này được mua năm ngoái.","Zhè jiàn yī fu shì qù nián mǎi de."],["我很喜欢穿这件衣服。","Tôi rất thích mặc chiếc áo này.","Wǒ hěn xǐ huan chuān zhè jiàn yī fu."],["有一次我和朋友去商店。","Có lần tôi đi cửa hàng cùng bạn.","Yǒu yí cì wǒ hé péng you qù shāng diàn."],["我看见一双蓝色的鞋。","Tôi nhìn thấy một đôi giày màu xanh dương.","Wǒ kàn jiàn yì shuāng lán sè de xié."],["我觉得这双鞋很漂亮。","Tôi thấy đôi giày này rất đẹp.","Wǒ jué de zhè shuāng xié hěn piào liang."],["但是这双鞋有点儿贵。","Nhưng đôi giày hơi đắt.","Dàn shì zhè shuāng xié yǒu diǎn ér guì."],["所以那天我没有买。","Vì vậy hôm đó tôi không mua.","Suǒ yǐ nà tiān wǒ méi yǒu mǎi."],["下次有钱的时候，我想买这双鞋。","Lần sau khi có tiền, tôi muốn mua đôi giày đó.","Xià cì yǒu qián de shí hou, wǒ xiǎng mǎi zhè shuāng xié."],["所以我还想买蓝色的东西。","Vì vậy tôi còn muốn mua thêm đồ màu xanh dương.","Suǒ yǐ wǒ hái xiǎng mǎi lán sè de dōng xi."]],"g":"C"},{"id":21,"q":"你觉得快乐的生活是什么样？","qvi":"Cuộc sống hạnh phúc","s":[["我觉得快乐的生活很简单。","Tôi thấy một cuộc sống hạnh phúc rất đơn giản.","Wǒ jué de kuài lè de shēng huó hěn jiǎn dān."],["我想让我的家人每天都很高兴。","Tôi muốn gia đình mình ngày nào cũng vui vẻ.","Wǒ xiǎng ràng wǒ de jiā rén měi tiān dōu hěn gāo xìng."],["我也想每天都很高兴。","Tôi cũng muốn mỗi ngày đều vui vẻ.","Wǒ yě xiǎng měi tiān dōu hěn gāo xìng."],["我喜欢和家人在一起。","Tôi thích ở bên gia đình.","Wǒ xǐ huan hé jiā rén zài yì qǐ."],["我们可以一起吃饭。","Chúng tôi có thể cùng ăn cơm.","Wǒ men kě yǐ yì qǐ chī fàn."],["吃饭的时候，我们可以说很多话。","Trong bữa ăn, chúng tôi có thể nói rất nhiều chuyện.","Chī fàn de shí hou, wǒ men kě yǐ shuō hěn duō huà."],["我也有几个很好的朋友。","Tôi cũng có vài người bạn rất tốt.","Wǒ yě yǒu jǐ ge hěn hǎo de péng you."],["周末我们经常一起出去玩。","Cuối tuần chúng tôi thường cùng nhau ra ngoài chơi.","Zhōu mò wǒ men jīng cháng yì qǐ chū qù wán."],["我觉得有朋友很好。","Tôi thấy có bạn bè rất tốt.","Wǒ jué de yǒu péng you hěn hǎo."],["我还想每天学习一点儿汉语。","Tôi còn muốn mỗi ngày học một chút tiếng Trung.","Wǒ hái xiǎng měi tiān xué xí yì diǎnr hàn yǔ."],["因为学习让我很高兴。","Bởi vì học tập khiến tôi vui vẻ.","Yīn wèi xué xí ràng wǒ hěn gāo xìng."],["有空儿的时候，我喜欢运动。","Khi rảnh, tôi thích chơi thể thao.","Yǒu kòngr de shí hou, wǒ xǐ huan yùn dòng."],["晚上我想早点睡觉。","Buổi tối tôi muốn đi ngủ sớm một chút.","Wǎn shang wǒ xiǎng zǎo diǎn shuì jiào."],["我不想每天都那么忙。","Tôi không muốn ngày nào cũng bận rộn như thế.","Wǒ bù xiǎng měi tiān dōu nà me máng."],["我觉得这样的生活很快乐。","Tôi thấy cuộc sống như vậy rất hạnh phúc.","Wǒ jué de zhè yàng de shēng huó hěn kuài lè."]],"g":"G"},{"id":22,"q":"你第一次学习汉语的时候，觉得怎么样？","qvi":"Lần đầu học tiếng Trung","s":[["我第一次学习汉语的时候很高兴。","Lần đầu học tiếng Trung, tôi rất vui.","Wǒ dì yī cì xué xí hàn yǔ de shí hou hěn gāo xìng."],["因为我以前没有学过汉语。","Bởi vì trước đây tôi chưa từng học tiếng Trung.","Yīn wèi wǒ yǐ qián méi yǒu xué guo hàn yǔ."],["第一天上课，我有点儿紧张。","Ngày đầu tiên lên lớp, tôi hơi hồi hộp.","Dì yì tiān shàng kè, wǒ yǒu diǎn ér jǐn zhāng."],["老师先让我们介绍自己。","Trước tiên giáo viên bảo chúng tôi giới thiệu bản thân.","Lǎo shī xiān ràng wǒ men jiè shào zì jǐ."],["那时候我只会说几句汉语。","Khi ấy tôi chỉ biết nói vài câu tiếng Trung.","Nà shí hou wǒ zhǐ huì shuō jǐ jù hàn yǔ."],["老师说话的时候，我经常听不懂。","Khi giáo viên nói, tôi thường nghe không hiểu.","Lǎo shī shuō huà de shí hou, wǒ jīng cháng tīng bu dǒng."],["写汉字对我也很难。","Viết chữ Hán đối với tôi cũng rất khó.","Xiě hàn zì duì wǒ yě hěn nán."],["但是老师很有意思。","Nhưng giáo viên rất thú vị.","Dàn shì lǎo shī hěn yǒu yì sī."],["他常常帮助我们。","Thầy thường giúp đỡ chúng tôi.","Tā cháng cháng bāng zhù wǒ men."],["同学也经常和我一起练习。","Bạn học cũng thường luyện tập cùng tôi.","Tóng xué yě jīng cháng hé wǒ yì qǐ liàn xí."],["下课以后，我就回家做作业。","Sau khi tan học, tôi về nhà làm bài tập.","Xià kè yǐ hòu, wǒ jiù huí jiā zuò zuò yè."],["每天我都练习听和说。","Mỗi ngày tôi đều luyện nghe và nói.","Měi tiān wǒ dōu liàn xí tīng hé shuō."],["过了一个月，我会说更多汉语了。","Sau một tháng, tôi đã biết nói nhiều tiếng Trung hơn.","Guo le yí ge yuè, wǒ huì shuō gèng duō hàn yǔ le."],["现在我觉得学习汉语很有意思。","Bây giờ tôi thấy học tiếng Trung rất thú vị.","Xiàn zài wǒ jué de xué xí hàn yǔ hěn yǒu yì sī."],["所以我每天都想学习汉语。","Vì thế tôi muốn học tiếng Trung mỗi ngày.","Suǒ yǐ wǒ měi tiān dōu xiǎng xué xí hàn yǔ."]],"g":"D"},{"id":23,"q":"你喜欢认识新朋友吗？为什么？","qvi":"Làm quen bạn mới","s":[["我很喜欢认识新朋友。","Tôi rất thích làm quen với bạn mới.","Wǒ hěn xǐ huan rèn shi xīn péng you."],["因为我觉得朋友很重要。","Bởi vì tôi nghĩ bạn bè rất quan trọng.","Yīn wèi wǒ jué de péng you hěn zhòng yào."],["现在我有几个很好的朋友。","Hiện tại tôi có vài người bạn rất tốt.","Xiàn zài wǒ yǒu jǐ ge hěn hǎo de péng you."],["他们以前都是我的同学。","Trước đây họ đều là bạn học của tôi.","Tā men yǐ qián dōu shì wǒ de tóng xué."],["我们经常一起学习。","Chúng tôi thường cùng nhau học tập.","Wǒ men jīng cháng yì qǐ xué xí."],["下课以后，我们也经常一起运动。","Sau khi tan học, chúng tôi cũng thường cùng nhau chơi thể thao.","Xià kè yǐ hòu, wǒ men yě jīng cháng yì qǐ yùn dòng."],["和朋友在一起，我很快乐。","Ở bên bạn bè, tôi rất vui.","Hé péng you zài yì qǐ, wǒ hěn kuài lè."],["我现在正在学习汉语。","Hiện tại tôi đang học tiếng Trung.","Wǒ xiàn zài zhèng zài xué xí hàn yǔ."],["所以我也想认识中国朋友。","Vì vậy tôi cũng muốn làm quen với bạn Trung Quốc.","Suǒ yǐ wǒ yě xiǎng rèn shi Zhōng guó péng you."],["有一次我认识了一个中国朋友。","Có lần tôi quen một người bạn Trung Quốc.","Yǒu yí cì wǒ rèn shi le yí ge Zhōng guó péng you."],["他会说汉语，也会说一点儿英语。","Bạn ấy nói được tiếng Trung và một chút tiếng Anh.","Tā huì shuō hàn yǔ, yě huì shuō yì diǎnr yīng yǔ."],["我经常和他练习汉语口语。","Tôi thường luyện nói tiếng Trung với bạn ấy.","Wǒ jīng cháng hé tā liàn xí hàn yǔ kǒu yǔ."],["有问题的时候，他会帮助我。","Khi có vấn đề, bạn ấy sẽ giúp tôi.","Yǒu wèn tí de shí hou, tā huì bāng zhù wǒ."],["我也可以帮助他学习越南语。","Tôi cũng có thể giúp bạn ấy học tiếng Việt.","Wǒ yě kě yǐ bāng zhù tā xué xí Yuè nán yǔ."],["所以我还想认识更多新朋友。","Vì vậy tôi còn muốn quen thêm nhiều bạn mới.","Suǒ yǐ wǒ hái xiǎng rèn shi gèng duō xīn péng you."]],"g":"A"},{"id":24,"q":"你收到过最好的礼物是什么？","qvi":"Món quà tuyệt vời nhất","s":[["我收到过很多礼物。","Tôi đã nhận được nhiều món quà.","Wǒ shōu dào guo hěn duō lǐ wù."],["但是我最喜欢一本汉语书。","Nhưng tôi thích nhất một cuốn sách tiếng Trung.","Dàn shì wǒ zuì xǐ huan yī běn hàn yǔ shū."],["这是妈妈送给我的礼物。","Đây là món quà mẹ tặng tôi.","Zhè shì mā ma sòng gěi wǒ de lǐ wù."],["去年我过生日的时候，妈妈买了这本书。","Năm ngoái vào sinh nhật tôi, mẹ mua cuốn sách này.","Qù nián wǒ guò shēng rì de shí hou, mā ma mǎi le zhè běn shū."],["那天她给我打电话。","Hôm đó mẹ gọi điện cho tôi.","Nà tiān tā gěi wǒ dǎ diàn huà."],["她说有一份礼物给我。","Mẹ nói có một món quà dành cho tôi.","Tā shuō yǒu yí fèn lǐ wù gěi wǒ."],["我回家以后，她把书给我。","Sau khi tôi về nhà, mẹ đưa sách cho tôi.","Wǒ huí jiā yǐ hòu, tā bǎ shū gěi wǒ."],["我看见这本书很高兴。","Nhìn thấy cuốn sách này, tôi rất vui.","Wǒ kàn jiàn zhè běn shū hěn gāo xìng."],["因为那时候我正在学习汉语。","Bởi vì lúc đó tôi đang học tiếng Trung.","Yīn wèi nà shí hou wǒ zhèng zài xué xí hàn yǔ."],["这本书里有很多汉字。","Trong cuốn sách này có rất nhiều chữ Hán.","Zhè běn shū lǐ yǒu hěn duō hàn zì."],["我每天都看这本书。","Tôi đọc cuốn sách này mỗi ngày.","Wǒ měi tiān dōu kàn zhè běn shū."],["有不懂的字，我就问老师。","Nếu có chữ không hiểu, tôi hỏi giáo viên.","Yǒu bù dǒng de zì, wǒ jiù wèn lǎo shī."],["现在我已经看过很多次了。","Bây giờ tôi đã đọc nó rất nhiều lần rồi.","Xiàn zài wǒ yǐ jīng kàn guo hěn duō cì le."],["我觉得这本书对我很重要。","Tôi thấy cuốn sách này rất quan trọng đối với tôi.","Wǒ jué de zhè běn shū duì wǒ hěn zhòng yào."],["所以这是我最喜欢的礼物。","Vì vậy đây là món quà tôi thích nhất.","Suǒ yǐ zhè shì wǒ zuì xǐ huan de lǐ wù."]],"g":"G"},{"id":25,"q":"你最想学会做什么事情？","qvi":"Điều muốn học nhất","s":[["我最想学会说好汉语。","Điều tôi muốn học nhất là nói tiếng Trung thật tốt.","Wǒ zuì xiǎng xué huì shuō hǎo hàn yǔ."],["因为我以后想在中国公司工作。","Bởi vì sau này tôi muốn làm việc tại công ty Trung Quốc.","Yīn wèi wǒ yǐ hòu xiǎng zài Zhōng guó gōng sī gōng zuò."],["我现在每天都学习汉语。","Hiện tại ngày nào tôi cũng học tiếng Trung.","Wǒ xiàn zài měi tiān dōu xué xí hàn yǔ."],["早上我去学校上课。","Buổi sáng tôi đến trường lên lớp.","Zǎo shang wǒ qù xué xiào shàng kè."],["上课的时候，我好好听老师说话。","Trong giờ học, tôi chăm chú nghe giáo viên nói.","Shàng kè de shí hou, wǒ hǎo hǎo tīng lǎo shī shuō huà."],["老师也让我们练习口语。","Giáo viên cũng yêu cầu chúng tôi luyện nói.","Lǎo shī yě ràng wǒ men liàn xí kǒu yǔ."],["但是我有时候说得不好。","Nhưng đôi khi tôi nói chưa tốt.","Dàn shì wǒ yǒu shí hou shuō de bù hǎo."],["有不懂的问题，我就问老师。","Nếu có vấn đề không hiểu, tôi hỏi giáo viên.","Yǒu bù dǒng de wèn tí, wǒ jiù wèn lǎo shī."],["老师会帮助我。","Giáo viên sẽ giúp tôi.","Lǎo shī huì bāng zhù wǒ."],["下课以后，我回家做作业。","Sau khi tan học, tôi về nhà làm bài tập.","Xià kè yǐ hòu, wǒ huí jiā zuò zuò yè."],["我也经常和同学一起练习。","Tôi cũng thường luyện tập cùng các bạn học.","Wǒ yě jīng cháng hé tóng xué yì qǐ liàn xí."],["我们每天说一个小时汉语。","Mỗi ngày chúng tôi nói tiếng Trung trong một tiếng.","Wǒ men měi tiān shuō yí ge xiǎo shí hàn yǔ."],["现在我能听懂很多话了。","Bây giờ tôi đã có thể nghe hiểu rất nhiều điều.","Xiàn zài wǒ néng tīng dǒng hěn duō huà le."],["我还想练习更多。","Tôi còn muốn luyện tập nhiều hơn.","Wǒ hái xiǎng liàn xí gèng duō."],["我想以后可以和中国人说好汉语。","Tôi muốn sau này có thể giao tiếp tiếng Trung thật tốt với người Trung Quốc.","Wǒ xiǎng yǐ hòu kě yǐ hé Zhōng guó rén shuō hǎo hàn yǔ."]],"g":"D"},{"id":26,"q":"你觉得在家休息好还是出去玩好？为什么？","qvi":"Ở nhà nghỉ hay ra ngoài chơi","s":[["我觉得在家休息和出去玩都很好。","Tôi thấy nghỉ ngơi ở nhà và ra ngoài chơi đều tốt.","Wǒ jué de zài jiā xiū xī hé chū qù wán dōu hěn hǎo."],["但是我累的时候更喜欢在家休息。","Nhưng khi mệt, tôi thích nghỉ ngơi ở nhà hơn.","Dàn shì wǒ lèi de shí hou gèng xǐ huan zài jiā xiū xī."],["因为我每天都要上课。","Bởi vì mỗi ngày tôi đều phải lên lớp.","Yīn wèi wǒ měi tiān dōu yào shàng kè."],["下课以后，我有时候很累。","Sau khi tan học, đôi khi tôi rất mệt.","Xià kè yǐ hòu, wǒ yǒu shí hou hěn lèi."],["这时候我就想回家。","Lúc ấy tôi muốn về nhà.","Zhè shí hou wǒ jiù xiǎng huí jiā."],["回家以后，我先喝一点儿水。","Về nhà, trước tiên tôi uống một chút nước.","Huí jiā yǐ hòu, wǒ xiān hē yì diǎnr shuǐ."],["然后我在家听音乐。","Sau đó tôi nghe nhạc ở nhà.","Rán hòu wǒ zài jiā tīng yīn yuè."],["有时候我也看一会儿电影。","Đôi khi tôi cũng xem phim một lát.","Yǒu shí hou wǒ yě kàn yí huìr diàn yǐng."],["休息以后，我觉得很舒服。","Sau khi nghỉ ngơi, tôi cảm thấy rất dễ chịu.","Xiū xī yǐ hòu, wǒ jué de hěn shū fu."],["但是周末我也喜欢出去玩。","Nhưng cuối tuần tôi cũng thích ra ngoài chơi.","Dàn shì zhōu mò wǒ yě xǐ huan chū qù wán."],["因为星期天我不上课。","Bởi vì Chủ Nhật tôi không có lớp.","Yīn wèi xīng qī tiān wǒ bù shàng kè."],["我可以和朋友一起去踢足球。","Tôi có thể cùng bạn bè đi đá bóng.","Wǒ kě yǐ hé péng you yì qǐ qù tī zú qiú."],["踢完足球，我们还可以一起吃饭。","Đá bóng xong, chúng tôi còn có thể cùng đi ăn.","Tī wán zú qiú, wǒ men hái kě yǐ yì qǐ chī fàn."],["和朋友在一起，我也很快乐。","Ở bên bạn bè, tôi cũng rất vui.","Hé péng you zài yì qǐ, wǒ yě hěn kuài lè."],["所以我累的时候在家休息，有空儿的时候出去玩。","Vì vậy khi mệt tôi nghỉ ở nhà, khi rảnh tôi ra ngoài chơi.","Suǒ yǐ wǒ lèi de shí hou zài jiā xiū xī, yǒu kòngr de shí hou chū qù wán."]],"g":"H"}];
// Cấu trúc câu dùng trong bài nói (re: biểu thức nhận diện, frame: khung câu gợi ý khi tự viết)
